import{_ as e,o as t,c as l,a0 as r}from"./chunks/framework.jwovEGr5.js";const p=JSON.parse('{"title":"防艾教育","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"中山大学/新生课程/防艾教育.md","filePath":"中山大学/新生课程/防艾教育.md"}'),o={name:"中山大学/新生课程/防艾教育.md"};function i(n,a,d,h,s,_){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="防艾教育" tabindex="-1">防艾教育 <a class="header-anchor" href="#防艾教育" aria-label="Permalink to &quot;防艾教育&quot;">​</a></h1><p>课程时间：2026.8.21 15:30~16:30</p><p>主讲：黄湛镰</p><h2 id="传染病特点" tabindex="-1">传染病特点 <a class="header-anchor" href="#传染病特点" aria-label="Permalink to &quot;传染病特点&quot;">​</a></h2><ol><li>病原体引起疾病</li><li>人与人传播、人与动物传播</li></ol><h3 id="传播途径" tabindex="-1">传播途径 <a class="header-anchor" href="#传播途径" aria-label="Permalink to &quot;传播途径&quot;">​</a></h3><p>呼吸道传播、消化道传播、血液体液传播、虫媒传播</p><h2 id="艾滋病" tabindex="-1">艾滋病 <a class="header-anchor" href="#艾滋病" aria-label="Permalink to &quot;艾滋病&quot;">​</a></h2><p>全称获得性免疫缺陷综合征，由人类免疫缺陷病毒（HIV）感染引起的慢性乙类传染病。</p><p>HIV专门破坏人体CD4+免疫淋巴细胞，慢慢摧毁免疫系统，后期会发生各种严重感染、肿瘤；目前无法彻底根治，但规范治疗可以接近正常人寿命。</p><h3 id="三大传播途径" tabindex="-1">三大传播途径 <a class="header-anchor" href="#三大传播途径" aria-label="Permalink to &quot;三大传播途径&quot;">​</a></h3><ol><li>性接触传播：无保护的同性、异性性行为，肛交风险更高</li><li>血液传播：共用吸毒针具；输入污染血液；消毒不到位的纹身、穿刺等</li><li>母婴传播：感染HIV的妈妈怀孕、分娩、哺乳传给宝宝</li></ol>',12)])])}const u=e(o,[["render",i]]);export{p as __pageData,u as default};
